const DesignCommonFieldsSchema = DesignDuplicateInputSchema.and(
  z
    .object({
      categories: z
        .array(z.string().max(255))
        .max(10)
        .superRefine((items, ctx) => {
          const seen = new Map()
          for (const [i, val] of items.entries()) {
            const key = JSON.stringify(val)
            if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
            else seen.set(key, i)
          }
        })
        .exactOptional()
        .openapi({ description: 'The list of categories applied to the design' }),
      generate_plain_content: z
        .boolean()
        .default(true)
        .exactOptional()
        .openapi({
          description:
            'If true, plain_content is always generated from html_content. If false, plain_content is not altered.',
        }),
      subject: z
        .string()
        .max(5000)
        .exactOptional()
        .openapi({ description: 'Subject of the Design.' }),
    })
    .openapi({ required: [] }),
)
  .openapi({ title: 'Design Common Fields' })
  .openapi('DesignCommonFields')

