const SegmentWriteV2Schema = z
  .object({
    name: z.string().min(1).max(100).openapi({ description: 'Name of the segment.' }),
    parent_list_ids: z
      .array(z.string())
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional()
      .openapi({
        description:
          'The array of list ids to filter contacts on when building this segment. It allows only one such list id for now. We will support more in future',
      }),
    query_dsl: z
      .string()
      .openapi({
        description: 'SQL query which will filter contacts based on the conditions provided',
      }),
  })
  .openapi({ required: ['name', 'query_dsl'], title: 'segment_write' })
  .openapi('SegmentWriteV2')

