export const getAccessSettingsActivityRoute = createRoute({
  method: 'get',
  path: '/access_settings/activity',
  tags: ['IP Access Management'],
  summary: 'Retrieve all recent access attempts',
  description:
    '**This endpoint allows you to retrieve a list of all of the IP addresses that recently attempted to access your account either through the User Interface or the API.**',
  operationId: 'GET_access_settings-activity',
  request: {
    query: z.object({
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            description: 'Limits the number of IPs to return.',
            in: 'query',
            name: 'limit',
            schema: { default: 20, type: 'integer' },
            required: false,
          },
        }),
    }),
    headers: z.object({ 'on-behalf-of': TraitOnBehalfOfSubuserOnBehalfOfParamsSchema }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              result: z
                .array(
                  z
                    .object({
                      allowed: z
                        .boolean()
                        .openapi({
                          description:
                            'Indicates if the IP address was granted access to the account.',
                        }),
                      auth_method: z
                        .string()
                        .openapi({
                          description: 'The authentication method used when attempting access.',
                        }),
                      first_at: z
                        .int()
                        .openapi({
                          description:
                            'A Unix timestamp indicating when the first access attempt was made.',
                        }),
                      ip: z
                        .string()
                        .openapi({
                          description: 'The IP addressed used during the access attempt.',
                        }),
                      last_at: z
                        .int()
                        .openapi({
                          description:
                            'A Unix timestamp indicating when the most recent access attempt was made',
                        }),
                      location: z
                        .string()
                        .openapi({
                          description:
                            'The geographic location from which the access attempt originated.',
                        }),
                    })
                    .openapi({
                      required: ['allowed', 'auth_method', 'first_at', 'ip', 'last_at', 'location'],
                    }),
                )
                .openapi({
                  description:
                    'An array containing the IPs that recently attempted to access your account.',
                }),
            })
            .openapi({ required: ['result'] }),
          examples: {
            response: {
              value: {
                result: [
                  {
                    allowed: false,
                    auth_method: 'Web',
                    first_at: 1444087966,
                    ip: '1.1.1.1',
                    last_at: 1444406672,
                    location: 'Australia',
                  },
                  {
                    allowed: false,
                    auth_method: 'Web',
                    first_at: 1444087505,
                    ip: '1.2.3.48',
                    last_at: 1444087505,
                    location: 'Mukilteo, Washington',
                  },
                ],
              },
            },
          },
        },
      },
    },
    401: TraitGlobalErrors_401Response,
    403: TraitGlobalErrors_403Response,
    404: TraitGlobalErrors_404Response,
    500: TraitGlobalErrors_500Response,
  },
  security: [{ Authorization: [] }],
})

