export const getContactdbRecipientsSearchRoute = createRoute({
  method: 'get',
  path: '/contactdb/recipients/search',
  tags: ['Contacts API - Recipients'],
  summary: 'Search recipients',
  description:
    "**This endpoint allows you to perform a search on all of your Marketing Campaigns recipients.**\n\nfield_name:\n\n* is a variable that is substituted for your actual custom field name from your recipient.\n* Text fields must be url-encoded. Date fields are searchable only by unix timestamp (e.g. 2/2/2015 becomes 1422835200)\n* If field_name is a 'reserved' date field, such as created_at or updated_at, the system will internally convert\nyour epoch time to a date range encompassing the entire day. For example, an epoch time of 1422835600 converts to\nMon, 02 Feb 2015 00:06:40 GMT, but internally the system will search from Mon, 02 Feb 2015 00:00:00 GMT through\nMon, 02 Feb 2015 23:59:59 GMT.",
  operationId: 'GET_contactdb-recipients-search',
  request: {
    query: z.object({
      '{field_name}': z
        .string()
        .exactOptional()
        .openapi({
          param: { in: 'query', name: '{field_name}', schema: { type: 'string' }, required: false },
        }),
    }),
    headers: z.object({ 'on-behalf-of': TraitOnBehalfOfSubuserOnBehalfOfParamsSchema }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({ recipients: z.array(ContactdbRecipientSchema).exactOptional() })
            .openapi({ required: [] }),
          examples: {
            response: {
              value: {
                recipients: [
                  {
                    created_at: 1422313607,
                    custom_fields: [{ id: 23, name: 'pet', type: 'text', value: 'Fluffy' }],
                    email: 'jones@example.com',
                    first_name: null,
                    id: 'YUBh',
                    last_clicked: null,
                    last_emailed: null,
                    last_name: 'Jones',
                    last_opened: null,
                    updated_at: 1422313790,
                  },
                ],
              },
            },
          },
        },
      },
    },
    400: {
      description:
        '"" : "Returned if no search params are specified"\n"field" : "Returned if the provided field is invalid or does not exist"',
      content: {
        'application/json': {
          schema: GlobalErrorResponseSchemaSchema,
          examples: {
            response: {
              value: {
                errors: [
                  {
                    message:
                      'The following parameters are not custom fields or reserved fields: [{field_name}]',
                  },
                  { message: 'No search params are specified' },
                ],
              },
            },
          },
        },
      },
    },
    401: {
      description: '',
      content: {
        'application/json': {
          schema: GlobalErrorResponseSchemaSchema,
          examples: {
            response: { value: { errors: [{ field: null, message: 'authorization required' }] } },
          },
        },
      },
    },
  },
  security: [{ Authorization: [] }],
})

export const postContactdbRecipientsSearchRoute = createRoute({
  method: 'post',
  path: '/contactdb/recipients/search',
  tags: ['Contacts API - Recipients'],
  summary: 'Search recipients',
  description:
    '<p>\n  Search using segment conditions without actually creating a segment.\n  Body contains a JSON object with <code>conditions</code>, a list of conditions as described below, and an optional <code>list_id</code>, which is a valid list ID for a list to limit the search on.\n</p>\n\n<p>\n  Valid operators for create and update depend on the type of the field for which you are searching.\n</p>\n\n<ul>\n  <li>Dates:\n    <ul>\n      <li>"eq", "ne", "lt" (before), "gt" (after)\n        <ul>\n          <li>You may use MM/DD/YYYY for day granularity or an epoch for second granularity.</li>\n        </ul>\n      </li>\n      <li>"empty", "not_empty"</li>\n      <li>"is within"\n        <ul>\n          <li>You may use an <a href="https://en.wikipedia.org/wiki/ISO_8601">ISO 8601 date format</a> or the # of days.</li>\n        </ul>\n      </li>\n    </ul>\n  </li>\n  <li>Text: "contains", "eq" (is - matches the full field), "ne" (is not - matches any field where the entire field is not the condition value), "empty", "not_empty"</li>\n  <li>Numbers: "eq", "lt", "gt", "empty", "not_empty"</li>\n  <li>Email Clicks and Opens: "eq" (opened), "ne" (not opened)</li>\n</ul>\n\n<p>\n  Field values must all be a string.\n</p>\n\n<p>\n  Search conditions using "eq" or "ne" for email clicks and opens should provide a "field" of either <code>clicks.campaign_identifier</code> or <code>opens.campaign_identifier</code>.\n  The condition value should be a string containing the id of a completed campaign.\n</p>\n\n<p>\n  Search conditions list may contain multiple conditions, joined by an "and" or "or" in the "and_or" field.\n  The first condition in the conditions list must have an empty "and_or", and subsequent conditions must all specify an "and_or".\n</p>',
  operationId: 'POST_contactdb-recipients-search',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              conditions: z.array(
                z
                  .any()
                  .openapi({
                    'x-and_or': '',
                    'x-field': 'birthday',
                    'x-operator': 'eq',
                    'x-value': '01/12/1985',
                  }),
              ),
              list_id: z.int32(),
            })
            .openapi({
              example: {
                conditions: [
                  { and_or: '', field: 'birthday', operator: 'eq', value: '01/12/1985' },
                  { and_or: '', field: 'birthday', operator: 'eq', value: '01/12/1985' },
                  { and_or: '', field: 'birthday', operator: 'eq', value: '01/12/1985' },
                  { and_or: '', field: 'birthday', operator: 'eq', value: '01/12/1985' },
                ],
                list_id: -27497588,
              },
              required: ['list_id', 'conditions'],
            }),
        },
      },
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              recipient_count: z.int().exactOptional(),
              recipients: z
                .array(
                  z
                    .object({
                      created_at: z.int().exactOptional(),
                      custom_fields: z
                        .array(
                          z
                            .object({
                              id: z.int().exactOptional(),
                              name: z.string().exactOptional(),
                              type: z.string().exactOptional(),
                              value: z.union([z.int(), z.string()]).exactOptional(),
                            })
                            .openapi({ required: [] }),
                        )
                        .exactOptional(),
                      email: z.string().exactOptional(),
                      first_name: z.string().exactOptional(),
                      id: z.string().exactOptional(),
                      last_clicked: z.int().exactOptional(),
                      last_emailed: z.int().exactOptional(),
                      last_opened: z.int().exactOptional(),
                      updated_at: z.int().exactOptional(),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional(),
            })
            .openapi({ required: [] }),
          examples: {
            response: {
              value: {
                recipient_count: 65190677,
                recipients: [
                  {
                    created_at: -27901208,
                    email: 'ut magna quis ipsum',
                    id: 'fugiat ad adipisicing ullamco',
                    last_emailed: 21626657,
                  },
                  {
                    created_at: 17466400,
                    email: 'sunt irure',
                    first_name: 'est',
                    id: 'et',
                    last_clicked: -23135244,
                    last_opened: -44593357,
                  },
                  {
                    created_at: -34495329,
                    email: 'reprehenderit incididunt velit Lorem esse',
                    id: 'esse Ut ad dolore',
                    last_clicked: 10164083,
                    last_opened: 34443062,
                  },
                  {
                    created_at: -37030673,
                    email: 'amet deserunt fugiat voluptate',
                    id: 'et exercitation commodo id laborum',
                    last_clicked: -10497425,
                  },
                  {
                    created_at: 3658435,
                    custom_fields: [
                      {
                        id: -5765608,
                        name: 'proident pariatur',
                        type: 'dolore ut',
                        value: 'do in magna mollit',
                      },
                      { id: -31131201, name: 'laborum mollit', type: 'veniam', value: 84434696 },
                    ],
                    email: 'labore veniam',
                    first_name: 'Ut cupidatat nulla deserunt adipisicing',
                    id: 'ad pariatur esse',
                    last_clicked: -52862671,
                    last_opened: -84227501,
                    updated_at: -56455352,
                  },
                ],
              },
            },
          },
        },
      },
    },
    400: { description: '' },
  },
  security: [{ Authorization: [] }],
})

