export const getMailSettingsRoute = createRoute({
  method: 'get',
  path: '/mail_settings',
  tags: ['Settings - Mail'],
  summary: 'Retrieve all mail settings',
  description:
    '**This endpoint allows you to retrieve a list of all mail settings.**\n\nEach setting will be returned with an `enabled` status set to `true` or `false` and a short description that explains what the setting does.',
  operationId: 'GET_mail_settings',
  request: {
    query: z.object({
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'The number of settings to return.',
            in: 'query',
            name: 'limit',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      offset: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Where in the list of results to begin displaying settings.',
            in: 'query',
            name: 'offset',
            schema: { type: 'integer' },
            required: false,
          },
        }),
    }),
    headers: z.object({ 'on-behalf-of': TraitOnBehalfOfSubuserOnBehalfOfParamsSchema }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              result: z
                .array(
                  z
                    .object({
                      description: z
                        .string()
                        .openapi({ description: 'A description of the mail setting.' }),
                      enabled: z
                        .boolean()
                        .openapi({
                          description: 'Indicates if this mail setting is currently enabled.',
                        }),
                      name: z.string().openapi({ description: 'The name of the mail setting.' }),
                      title: z.string().openapi({ description: 'The title of the mail setting.' }),
                    })
                    .openapi({ required: ['title', 'enabled', 'name', 'description'] }),
                )
                .openapi({ description: 'The list of all mail settings.' }),
            })
            .openapi({ required: ['result'] }),
          examples: {
            response: {
              value: {
                result: [
                  {
                    description: 'Address / domains that should never have email suppressed.',
                    enabled: false,
                    name: 'address_whitelist',
                    title: 'Address Whitelist',
                  },
                  {
                    description:
                      'Allows you to automatically purge bounce records from SendGrid after a specified number of days.',
                    enabled: false,
                    name: 'bounce_purge',
                    title: 'Bounce Purge',
                  },
                  {
                    description:
                      'Controls notifications for events, such as bounces, clicks, and opens.',
                    enabled: true,
                    name: 'event_notify',
                    title: 'Event Notification',
                  },
                  {
                    description: 'Allows you to add a custom footer to outgoing email.',
                    enabled: false,
                    name: 'footer',
                    title: 'Footer',
                  },
                  {
                    description: 'Allows you to forward bounces to a specific email address.',
                    enabled: true,
                    name: 'forward_bounce',
                    title: 'Forward Bounce',
                  },
                  {
                    description:
                      'Allows for a copy of spam reports to be forwarded to an email address.',
                    enabled: false,
                    name: 'forward_spam',
                    title: 'Forward Spam',
                  },
                  {
                    description: 'Allows you to customize your outgoing HTML emails.',
                    enabled: true,
                    name: 'template',
                    title: 'Legacy Email Template',
                  },
                  {
                    description: 'Convert your plain text emails to HTML.',
                    enabled: false,
                    name: 'plain_content',
                    title: 'Plain Content',
                  },
                  {
                    description: 'Check outbound messages for spam content.',
                    enabled: true,
                    name: 'spam_check',
                    title: 'Spam Checker',
                  },
                ],
              },
            },
          },
        },
      },
    },
    400: TraitMakoErrorResponse_400Response,
    401: TraitMakoErrorResponse_401Response,
    403: TraitMakoErrorResponse_403Response,
    404: TraitMakoErrorResponse_404Response,
    500: TraitMakoErrorResponse_500Response,
  },
  security: [{ Authorization: [] }],
})

export const getMailSettingsAddressWhitelistRoute = createRoute({
  method: 'get',
  path: '/mail_settings/address_whitelist',
  tags: ['Settings - Mail'],
  summary: 'Retrieve address whitelist mail settings',
  description:
    '**This endpoint allows you to retrieve your current email address whitelist settings.**\n\nThe Address Whitelist setting allows you to specify email addresses or domains for which mail should never be suppressed.\n\nFor example, if you own the domain `example.com`, and one or more of your recipients use `email@example.com` addresses, placing `example.com` in the address whitelist setting instructs Twilio SendGrid to ignore all bounces, blocks, and unsubscribes logged for that domain. In other words, all bounces, blocks, and unsubscribes will still be sent to `example.com` as if they were sent under normal sending conditions.',
  operationId: 'GET_mail_settings-address_whitelist',
  request: { headers: z.object({ 'on-behalf-of': TraitOnBehalfOfSubuserOnBehalfOfParamsSchema }) },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: MailSettingsAddressWhitelabelSchema,
          examples: {
            response: { value: { enabled: true, list: ['example.com', 'jane_doe@example1.com'] } },
          },
        },
      },
    },
    400: TraitMakoErrorResponse_400Response,
    401: TraitMakoErrorResponse_401Response,
    403: TraitMakoErrorResponse_403Response,
    404: TraitMakoErrorResponse_404Response,
    500: TraitMakoErrorResponse_500Response,
  },
  security: [{ Authorization: [] }],
})

export const patchMailSettingsAddressWhitelistRoute = createRoute({
  method: 'patch',
  path: '/mail_settings/address_whitelist',
  tags: ['Settings - Mail'],
  summary: 'Update address whitelist mail settings',
  description:
    "**This endpoint allows you to update your current email address whitelist settings.**\n\nYou can select whether or not this setting should be enabled by assigning the `enabled` field a `true` or `false` value.\n\nPassing only the `enabled` field to this endpoint will not alter your current `list` of whitelist entries. However, any modifications to your `list` of entries will overwrite the entire list. For this reason, you must included all existing entries you wish to retain in your `list` in addition to any new entries you intend to add. To remove one or more `list` entries, pass a `list` with only the entries you wish to retain.\n\nYou should not add generic domains such as `gmail.com` or `yahoo.com`  in your `list` because your emails will not honor recipients' unsubscribes. This may cause a legal violation of [CAN-SPAM](https://sendgrid.com/docs/glossary/can-spam/) and could damage your sending reputation.\n\nThe Address Whitelist setting allows you to specify email addresses or domains for which mail should never be suppressed.\n\nFor example, if you own the domain `example.com`, and one or more of your recipients use `email@example.com` addresses, placing `example.com` in the address whitelist setting instructs Twilio SendGrid to ignore all bounces, blocks, and unsubscribes logged for that domain. In other words, all bounces, blocks, and unsubscribes will still be sent to `example.com` as if they were sent under normal sending conditions.",
  operationId: 'PATCH_mail_settings-address_whitelist',
  request: {
    headers: z.object({ 'on-behalf-of': TraitOnBehalfOfSubuserOnBehalfOfParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              enabled: z
                .boolean()
                .exactOptional()
                .openapi({ description: 'Indicates if your email address whitelist is enabled.' }),
              list: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  description:
                    'Either a single email address that you want whitelisted or a domain, for which all email addresses belonging to this domain will be whitelisted.',
                }),
            })
            .openapi({
              example: { enabled: true, list: ['email1@example.com', 'example.com'] },
              required: [],
            }),
        },
      },
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: MailSettingsAddressWhitelabelSchema,
          examples: { response: { value: { enabled: true, list: ['email1@example.com'] } } },
        },
      },
    },
    400: TraitMakoErrorResponse_400Response,
    401: TraitMakoErrorResponse_401Response,
    403: TraitMakoErrorResponse_403Response,
    404: TraitMakoErrorResponse_404Response,
    500: TraitMakoErrorResponse_500Response,
  },
  security: [{ Authorization: [] }],
})

export const getMailSettingsBouncePurgeRoute = createRoute({
  method: 'get',
  path: '/mail_settings/bounce_purge',
  tags: ['Settings - Mail'],
  summary: 'Retrieve bounce purge mail settings',
  description:
    "**This endpoint allows you to retrieve your current bounce and purge settings.**\n\nThe Bounce Perge setting allows you to set a schedule that Twilio SendGrid will use to automatically delete contacts from your soft and hard bounce suppression lists.\n\nA hard bounce occurs when an email message has been returned to the sender because the recipient's address is invalid. A hard bounce might occur because the domain name doesn't exist or because the recipient is unknown.\n\nA soft bounce occurs when an email message reaches the recipient's mail server but is bounced back undelivered before it actually reaches the recipient. A soft bounce might occur because the recipient's inbox is full.\n\nYou can also manage this setting in the [Mail Settings section of the Twilio SendGrid App](https://app.sendgrid.com/settings/mail_settings). You can manage your bounces manually using the [Bounces API](https://sendgrid.api-docs.io/v3.0/bounces-api) or the [Bounces menu in the Twilio SendGrid App](https://app.sendgrid.com/suppressions/bounces).",
  operationId: 'GET_mail_settings-bounce_purge',
  request: { headers: z.object({ 'on-behalf-of': TraitOnBehalfOfSubuserOnBehalfOfParamsSchema }) },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: MailSettingsBouncePurgeSchema,
          examples: { response: { value: { enabled: false, hard_bounces: 5, soft_bounces: 5 } } },
        },
      },
    },
    400: TraitMakoErrorResponse_400Response,
    401: TraitMakoErrorResponse_401Response,
    403: TraitMakoErrorResponse_403Response,
    404: TraitMakoErrorResponse_404Response,
    500: TraitMakoErrorResponse_500Response,
  },
  security: [{ Authorization: [] }],
})

export const patchMailSettingsBouncePurgeRoute = createRoute({
  method: 'patch',
  path: '/mail_settings/bounce_purge',
  tags: ['Settings - Mail'],
  summary: 'Update bounce purge mail settings',
  description:
    "**This endpoint allows you to update your current bounce and purge settings.**\n\nThe Bounce Perge setting allows you to set a schedule that Twilio SendGrid will use to automatically delete contacts from your soft and hard bounce suppression lists. The schedule is set in full days by assigning the number of days, an integer, to the `soft_bounces` and/or `hard_bounces` fields.\n\nA hard bounce occurs when an email message has been returned to the sender because the recipient's address is invalid. A hard bounce might occur because the domain name doesn't exist or because the recipient is unknown.\n\nA soft bounce occurs when an email message reaches the recipient's mail server but is bounced back undelivered before it actually reaches the recipient. A soft bounce might occur because the recipient's inbox is full.\n\nYou can also manage this setting in the [Mail Settings section of the Twilio SendGrid App](https://app.sendgrid.com/settings/mail_settings). You can manage your bounces manually using the [Bounces API](https://sendgrid.api-docs.io/v3.0/bounces-api) or the [Bounces menu in the Twilio SendGrid App](https://app.sendgrid.com/suppressions/bounces).",
  operationId: 'PATCH_mail_settings-bounce_purge',
  request: {
    headers: z.object({ 'on-behalf-of': TraitOnBehalfOfSubuserOnBehalfOfParamsSchema }),
    body: { content: { 'application/json': { schema: MailSettingsBouncePurgeSchema } } },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: MailSettingsBouncePurgeSchema,
          examples: { response: { value: { enabled: false, hard_bounces: 5, soft_bounces: 5 } } },
        },
      },
    },
    400: TraitMakoErrorResponse_400Response,
    401: TraitMakoErrorResponse_401Response,
    403: TraitMakoErrorResponse_403Response,
    404: TraitMakoErrorResponse_404Response,
    500: TraitMakoErrorResponse_500Response,
  },
  security: [{ Authorization: [] }],
})

