export const getMarketingListsRoute = createRoute({
  method: 'get',
  path: '/marketing/lists',
  tags: ['Lists'],
  summary: 'Get All Lists',
  description: '**This endpoint returns an array of all of your contact lists.**',
  operationId: 'GET_mc-lists',
  request: {
    query: z.object({
      page_size: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(1).max(1000),
        )
        .default(100)
        .exactOptional()
        .openapi({
          param: {
            description: 'Maximum number of elements to return. Defaults to 100, returns 1000 max',
            in: 'query',
            name: 'page_size',
            required: false,
            schema: { default: 100, maximum: 1000, minimum: 1, type: 'number' },
          },
        }),
      page_token: z
        .string()
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'page_token', required: false, schema: { type: 'string' } },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              _metadata: Metadata2Schema.exactOptional(),
              result: z.array(ListSchema).exactOptional(),
            })
            .openapi({ required: [] }),
          examples: {
            response: {
              value: {
                _metadata: {
                  self: 'https://api.sendgrid.com/v3/marketing/lists?page_size=100&page_token=',
                },
                result: [
                  {
                    _metadata: {
                      self: 'https://api.sendgrid.com/v3/marketing/lists/abc12312-x3y4-1234-abcd-123qwe456rty',
                    },
                    contact_count: 0,
                    id: 'abc12312-x3y4-1234-abcd-123qwe456rty',
                    name: 'list-name',
                  },
                ],
              },
            },
          },
        },
      },
    },
  },
  security: [{ Authorization: [] }],
})

