export const getMarketingSegmentsRoute = createRoute({
  method: 'get',
  path: '/marketing/segments',
  tags: ['segmenting contacts', 'Segmenting Contacts'],
  summary: 'Get List of Segments',
  description:
    '**This endpoint allows you to retrieve a list of segments.**\n\nThe query param `parent_list_ids` is treated as a filter.  Any match will be returned.  0 matches will return a response code of 200 with an empty `results` array.\n\n`parent_list_ids` | `no_parent_list_id` | `result`\n-----------------:|:--------------------:|:-------------\nempty | false | all segments\nvalues | false | segments filtered by list_ids\nvalues | true | segments filtered by list_ids and segments with no parent list_ids\nempty | true | segments with no parent list_ids',
  operationId: 'GET_marketing-segments',
  request: {
    query: z.object({
      parent_list_ids: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'A comma separated list of list ids to be used when searching for segments with the specified parent_list_id, no more than 50 is allowed',
            in: 'query',
            name: 'parent_list_ids',
            schema: { type: 'string' },
            required: false,
          },
        }),
      no_parent_list_id: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            description:
              "If set to `true` segments with an empty value of `parent_list_id` will be returned in the filter.  If the value is not present it defaults to 'false'.",
            in: 'query',
            name: 'no_parent_list_id',
            schema: { default: false, type: 'boolean' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              results: z
                .array(SegmentSummarySchema)
                .min(0)
                .superRefine((items, ctx) => {
                  const seen = new Map()
                  for (const [i, val] of items.entries()) {
                    const key = JSON.stringify(val)
                    if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                    else seen.set(key, i)
                  }
                }),
            })
            .openapi({ required: ['results'] }),
          examples: {
            response: {
              value: {
                results: [
                  {
                    contacts_count: 78434802,
                    created_at: '2921-01-27T19:33:36.479Z',
                    id: '12099613-91e5-4d09-a900-df7626325288',
                    sample_updated_at: '4685-11-26T07:05:04.660Z',
                    updated_at: '2883-07-10T13:13:37.697Z',
                  },
                  {
                    contacts_count: 34177253,
                    created_at: '2575-07-26T23:17:20.984Z',
                    id: '60c37015-3734-4c8e-b293-68cfa2ae4fa5',
                    name: 'amet',
                    parent_list_id: 'fd38af3d-3f69-4947-8dca-5fa967e7be82',
                    sample_updated_at: '3074-09-04T09:49:58.127Z',
                    updated_at: '5116-10-15T07:37:40.838Z',
                  },
                ],
              },
            },
          },
        },
      },
    },
    401: TraitGlobalErrors_401Response,
    403: TraitGlobalErrors_403Response,
    404: TraitGlobalErrors_404Response,
    500: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z.array(z.object({ message: z.string() }).openapi({ required: ['message'] })),
            })
            .openapi({ required: ['errors'] }),
        },
      },
    },
  },
  security: [{ Authorization: [] }],
})

