export const postMarketingSendersRoute = createRoute({
  method: 'post',
  path: '/marketing/senders',
  tags: ['Senders'],
  summary: 'Create a Sender Identity',
  description:
    '**This endpoint allows you to create a new sender identity.**\n\n*You may create up to 100 unique sender identities.*\n\nSender identities are required to be verified before use. If your domain has been authenticated, a new sender identity will auto verify on creation. Otherwise an email will be sent to the `from.email`.',
  operationId: 'POST_marketing-senders',
  request: {
    headers: z.object({ 'on-behalf-of': TraitOnBehalfOfSubuserOnBehalfOfParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              address: z
                .string()
                .openapi({ description: 'The physical address of the sender identity.' }),
              address_2: z
                .string()
                .exactOptional()
                .openapi({ description: 'Additional sender identity address information.' }),
              city: z.string().openapi({ description: 'The city of the sender identity.' }),
              country: z.string().openapi({ description: 'The country of the sender identity.' }),
              from: z
                .object({
                  email: z
                    .string()
                    .openapi({
                      description:
                        'This is where the email will appear to originate from for your recipient',
                    }),
                  name: z
                    .string()
                    .openapi({
                      description:
                        'This is the name appended to the from email field. IE - Your name or company name.',
                    }),
                })
                .openapi({ required: ['email', 'name'] }),
              nickname: z
                .string()
                .openapi({
                  description: 'A nickname for the sender identity. Not used for sending.',
                }),
              reply_to: z
                .object({
                  email: z
                    .string()
                    .openapi({
                      description: 'This is the email that your recipient will reply to.',
                    }),
                  name: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description:
                        'This is the name appended to the reply to email field. IE - Your name or company name.',
                    }),
                })
                .exactOptional()
                .openapi({ required: ['email'] }),
              state: z
                .string()
                .exactOptional()
                .openapi({ description: 'The state of the sender identity.' }),
              zip: z
                .string()
                .exactOptional()
                .openapi({ description: 'The zipcode of the sender identity.' }),
            })
            .openapi({
              example: {
                address: '1234 Fake St.',
                address_2: '',
                city: 'San Francisco',
                country: 'United States',
                from: { email: 'orders@example.com', name: 'Example Orders' },
                nickname: 'Example Orders',
                reply_to: { email: 'support@example.com', name: 'Example Support' },
                state: 'CA',
                zip: '94105',
              },
              required: ['nickname', 'from', 'address', 'city', 'country'],
            }),
        },
      },
    },
  },
  responses: {
    201: { description: '', content: { 'application/json': { schema: SenderIDSchema } } },
    401: TraitGlobalErrors_401Response,
    403: TraitGlobalErrors_403Response,
    404: TraitGlobalErrors_404Response,
    500: TraitGlobalErrors_500Response,
  },
  security: [{ Authorization: [] }],
})

