export const getMarketingStatsAutomationsRoute = createRoute({
  method: 'get',
  path: '/marketing/stats/automations',
  tags: ['Marketing Campaigns Stats'],
  summary: 'Get All Automation Stats',
  description:
    '**This endpoint allows you to retrieve stats for all your Automations.**\n\nBy default, all of your Automations will be returned, but you can specify a selection by passing in a comma-separated list of Automation IDs as the value of the query string parameter `automation_ids`.\n\nResponses are paginated. You can limit the number of responses returned per batch using the `page_size` query string parameter. The default is 50, but you specify a value between 1 and 100.\n\nYou can retrieve a specific page of responses with the `page_token` query string parameter.',
  operationId: 'getall-automation-stats',
  request: {
    query: z.object({
      automation_ids: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()).min(1).max(25),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'This endpoint returns all automation IDs if no `automation_ids` are specified.',
            explode: false,
            in: 'query',
            name: 'automation_ids',
            schema: { items: { type: 'string' }, maxItems: 25, minItems: 1, type: 'array' },
            style: 'form',
            required: false,
          },
        }),
      page_size: TraitPaginationPageSizeParamsSchema,
      page_token: TraitPaginationPageTokenParamsSchema,
    }),
  },
  responses: {
    200: {
      description: '',
      content: { 'application/json': { schema: AutomationsResponseSchema } },
    },
    400: {
      description: '',
      content: { 'application/json': { schema: GlobalErrorResponseSchemaSchema } },
    },
  },
  security: [{ Authorization: [] }],
})

