export const postSsoCertificatesRoute = createRoute({
  method: 'post',
  path: '/sso/certificates',
  tags: ['Certificates'],
  summary: 'Create an SSO Certificate',
  description: '**This endpoint allows you to create an SSO certificate.**',
  operationId: 'POST_sso-certificates',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              enabled: z
                .boolean()
                .exactOptional()
                .openapi({ description: 'Indicates if the certificate is enabled.' }),
              integration_id: z
                .string()
                .openapi({
                  description:
                    'An ID that matches a certificate to a specific IdP integration. This is the `id` returned by the "Get All SSO Integrations" endpoint.',
                }),
              public_certificate: z
                .string()
                .openapi({
                  description:
                    'This public certificate allows SendGrid to verify that SAML requests it receives are signed by an IdP that it recognizes.',
                }),
            })
            .openapi({
              description: '',
              example: {
                enabled: false,
                integration_id: 'b0b98502-9408-4b24-9e3d-31ed7cb15312',
                public_certificate: '<your x509 certificate>',
              },
              required: ['public_certificate', 'integration_id'],
            }),
        },
      },
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: SsoCertificateBodySchema,
          examples: {
            response: {
              value: {
                id: 66138975,
                intergration_id: 'b0b98502-9408-4b24-9e3d-31ed7cb15312',
                not_after: 1621289880,
                not_before: 1621289880,
                public_certificate: '<your x509 certificate>',
              },
            },
          },
        },
      },
    },
    400: TraitSingleSignOnErrorsTrait_400Response,
    401: TraitSingleSignOnErrorsTrait_401Response,
    403: TraitSingleSignOnErrorsTrait_403Response,
    429: TraitSingleSignOnErrorsTrait_429Response,
    500: TraitSingleSignOnErrorsTrait_500Response,
  },
})

