export const getSubusersSubuserNameStatsMonthlyRoute = createRoute({
  method: 'get',
  path: '/subusers/{subuser_name}/stats/monthly',
  tags: ['Subuser Statistics'],
  summary: 'Retrieve the monthly email statistics for a single subuser',
  description:
    '**This endpoint allows you to retrive the monthly email statistics for a specific subuser.**\n\nWhen using the `sort_by_metric` to sort your stats by a specific metric, you can not sort by the following metrics:\n`bounce_drops`, `deferred`, `invalid_emails`, `processed`, `spam_report_drops`, `spam_reports`, or `unsubscribe_drops`.',
  operationId: 'GET_subusers-subuser_name-stats-monthly',
  request: {
    params: z.object({
      subuser_name: z
        .string()
        .openapi({
          param: { in: 'path', name: 'subuser_name', required: true, schema: { type: 'string' } },
        }),
    }),
    query: z.object({
      date: z
        .string()
        .openapi({
          param: {
            description:
              'The date of the month to retrieve statistics for. Must be formatted YYYY-MM-DD',
            in: 'query',
            name: 'date',
            required: true,
            schema: { type: 'string' },
          },
        }),
      sort_by_metric: z
        .string()
        .default('delivered')
        .exactOptional()
        .openapi({
          param: {
            description:
              "The metric that you want to sort by. Metrics that you can sort by are: `blocks`, `bounces`, `clicks`, `delivered`, `opens`, `requests`, `unique_clicks`, `unique_opens`, and `unsubscribes`.'",
            in: 'query',
            name: 'sort_by_metric',
            required: false,
            schema: { default: 'delivered', type: 'string' },
          },
        }),
      sort_by_direction: z
        .enum(['desc', 'asc'])
        .default('desc')
        .exactOptional()
        .openapi({
          param: {
            description: 'The direction you want to sort.',
            in: 'query',
            name: 'sort_by_direction',
            required: false,
            schema: { default: 'desc', enum: ['desc', 'asc'], type: 'string' },
          },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(5)
        .exactOptional()
        .openapi({
          param: {
            description: 'Optional field to limit the number of results returned.',
            in: 'query',
            name: 'limit',
            required: false,
            schema: { default: 5, type: 'integer' },
          },
        }),
      offset: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(0)
        .exactOptional()
        .openapi({
          param: {
            description: 'Optional beginning point in the list to retrieve from.',
            in: 'query',
            name: 'offset',
            required: false,
            schema: { default: 0, type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: SubuserStatsSchema,
          examples: {
            response: {
              value: {
                date: '2016-02-01',
                stats: [
                  {
                    first_name: 'John',
                    last_name: 'Doe',
                    metrics: {
                      blocks: 0,
                      bounce_drops: 0,
                      bounces: 0,
                      clicks: 5,
                      deferred: 0,
                      delivered: 0,
                      invalid_emails: 0,
                      opens: 10,
                      processed: 10,
                      requests: 10,
                      spam_report_drops: 0,
                      spam_reports: 0,
                      unique_clicks: 0,
                      unique_opens: 0,
                      unsubscribe_drops: 0,
                      unsubscribes: 0,
                    },
                    name: 'user1',
                    type: 'subuser',
                  },
                ],
              },
            },
          },
        },
      },
    },
  },
  security: [{ Authorization: [] }],
})

