export const postTeammatesRoute = createRoute({
  method: 'post',
  path: '/teammates',
  tags: ['Teammates'],
  summary: 'Invite teammate',
  description:
    "**This endpoint allows you to invite a Teammate to your account via email.**\n\nYou can set a Teammate's initial permissions using the `scopes` array in the request body. Teammate's will receive a minimum set of scopes from Twilio SendGrid that are necessary for the Teammate to function.\n\n**Note:** A teammate invite will expire after 7 days, but you may resend the invitation at any time to reset the expiration date.",
  operationId: 'POST_v3-teammates',
  request: {
    headers: z.object({ 'on-behalf-of': TraitOnBehalfOfSubuserOnBehalfOfParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              email: z
                .string()
                .regex(/^.*@.*\..*/)
                .min(5)
                .max(255)
                .openapi({ description: "New teammate's email" }),
              is_admin: z
                .boolean()
                .default(false)
                .openapi({ description: 'Set to true if teammate should be an admin user' }),
              scopes: z
                .array(z.string())
                .openapi({
                  description:
                    'Set to specify list of scopes that teammate should have. Should be empty if teammate is an admin.',
                }),
            })
            .openapi({
              example: {
                email: 'teammate1@example.com',
                is_admin: false,
                scopes: ['user.profile.read', 'user.profile.update'],
              },
              required: ['email', 'scopes', 'is_admin'],
            }),
        },
      },
    },
  },
  responses: {
    201: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              email: z
                .string()
                .exactOptional()
                .openapi({ description: "Teammate's email address" }),
              is_admin: z
                .boolean()
                .exactOptional()
                .openapi({ description: 'Set to true if teammate should have admin privileges' }),
              scopes: z
                .array(z.any())
                .exactOptional()
                .openapi({
                  description:
                    'Initial set of permissions to give to teammate if they accept the invite',
                }),
              token: z
                .string()
                .exactOptional()
                .openapi({ description: 'Token to identify invite' }),
            })
            .openapi({ required: [] }),
          examples: {
            response: {
              value: {
                email: 'teammate1@example.com',
                is_admin: false,
                scopes: ['user.profile.read', 'user.profile.update'],
              },
            },
          },
        },
      },
    },
    400: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z
                .array(
                  z
                    .object({
                      field: z.string().exactOptional(),
                      message: z.string().exactOptional(),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  security: [{ Authorization: [] }],
})

