export const getTemplatesRoute = createRoute({
  method: 'get',
  path: '/templates',
  tags: ['Transactional Templates'],
  summary: 'Retrieve paged transactional templates.',
  description: '**This endpoint allows you to retrieve all transactional templates.**',
  operationId: 'GET_templates',
  request: {
    query: z.object({
      generations: z
        .enum(['legacy', 'dynamic', 'legacy,dynamic'])
        .default('legacy')
        .exactOptional()
        .openapi({
          param: {
            description:
              'Comma-delimited list specifying which generations of templates to return. Options are `legacy`, `dynamic` or `legacy,dynamic`.',
            in: 'query',
            name: 'generations',
            required: false,
            schema: {
              default: 'legacy',
              enum: ['legacy', 'dynamic', 'legacy,dynamic'],
              type: 'string',
            },
          },
        }),
      page_size: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(1).max(200),
        )
        .openapi({
          param: {
            description: 'The number of templates to be returned in each page of results',
            in: 'query',
            name: 'page_size',
            required: true,
            schema: { maximum: 200, minimum: 1, type: 'number' },
          },
        }),
      page_token: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'A token corresponding to a specific page of results, as provided by metadata',
            in: 'query',
            name: 'page_token',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
    headers: z.object({ 'on-behalf-of': TraitOnBehalfOfSubuserOnBehalfOfParamsSchema }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              _metadata: MetadataSchema.exactOptional(),
              result: z
                .array(TransactionalTemplatesTemplateLeanSchema)
                .exactOptional()
                .openapi({ description: '' }),
            })
            .openapi({ required: [] }),
          examples: {
            response: {
              value: {
                _metadata: { count: 1, self: 'https://api.sendgrid.com/v3/templates' },
                result: [
                  {
                    generation: 'legacy',
                    id: 'fae7c985-eb92-4b47-9987-28ec29dbc698',
                    name: 'example_name',
                    'updated_at ': '2020-11-12 12:00:09',
                    versions: [],
                  },
                ],
              },
            },
          },
        },
      },
    },
    400: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z
                .array(
                  z
                    .object({
                      '': z.string().exactOptional(),
                      error_id: z.string().exactOptional(),
                      message: z.string().exactOptional(),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  security: [{ Authorization: [] }],
})

