export const postValidationsEmailRoute = createRoute({
  method: 'post',
  path: '/validations/email',
  tags: ['Email Address Validation'],
  summary: 'Validate an email',
  description: '**This endpoint allows you to validate an email address.**',
  operationId: 'POST_validations-email',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              email: z
                .string()
                .openapi({ description: 'The email address that you want to validate.' }),
              source: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'A one-word classifier for where this validation originated.',
                }),
            })
            .openapi({
              example: { email: 'example@example.com', source: 'signup' },
              required: ['email'],
            }),
        },
      },
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              result: z
                .object({
                  checks: z
                    .object({
                      additional: z
                        .object({
                          has_known_bounces: z
                            .boolean()
                            .openapi({
                              description:
                                'WHether email sent to this address from your account has bounced.',
                            }),
                          has_suspected_bounces: z
                            .boolean()
                            .openapi({
                              description:
                                'Whether our model predicts that the email address might bounce.',
                            }),
                        })
                        .openapi({
                          description: 'Additional checks on the email address.',
                          required: ['has_known_bounces', 'has_suspected_bounces'],
                        }),
                      domain: z
                        .object({
                          has_mx_or_a_record: z
                            .boolean()
                            .openapi({
                              description:
                                'Whether the email has appropriate DNS records to deliver a message. ',
                            }),
                          has_valid_address_syntax: z
                            .boolean()
                            .openapi({ description: 'Whether the email address syntax is valid.' }),
                          is_suspected_disposable_address: z
                            .boolean()
                            .openapi({
                              description:
                                'Whether the domain appears to be from a disposable email address service.',
                            }),
                        })
                        .openapi({
                          description: 'Checks on the domain portion of the email address.',
                          required: [
                            'has_valid_address_syntax',
                            'has_mx_or_a_record',
                            'is_suspected_disposable_address',
                          ],
                        }),
                      local_part: z
                        .object({
                          is_suspected_role_address: z
                            .boolean()
                            .openapi({
                              description:
                                'Whether the local part of email appears to be a role or group (e.g., hr, admin)',
                            }),
                        })
                        .openapi({
                          description: 'Checks on the local part of the email address.',
                          required: ['is_suspected_role_address'],
                        }),
                    })
                    .openapi({
                      description: 'Granular checks for email address validity.',
                      required: ['domain', 'local_part', 'additional'],
                    }),
                  email: z.email().openapi({ description: 'The email being validated' }),
                  host: z.hostname().openapi({ description: 'The domain of the email address.' }),
                  ip_address: z
                    .string()
                    .openapi({ description: 'The IP address associated with this email.' }),
                  local: z
                    .string()
                    .openapi({ description: 'The local part of the email address.' }),
                  score: z
                    .number()
                    .openapi({ description: 'A numeric representation of the email validity.' }),
                  source: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description: 'The source of the validation, as per the API request.',
                    }),
                  suggestion: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description:
                        'A suggested correction in the event of domain name typos (e.g., gmial.com)',
                    }),
                  verdict: z
                    .enum(['Valid', 'Risky', 'Invalid'])
                    .openapi({
                      description:
                        'A generic classification of whether or not the email address is valid.',
                    }),
                })
                .openapi({
                  required: ['email', 'verdict', 'score', 'local', 'host', 'checks', 'ip_address'],
                }),
            })
            .openapi({ required: ['result'] }),
          examples: {
            response: {
              value: {
                result: {
                  checks: {
                    additional: { has_known_bounces: false, has_suspected_bounces: false },
                    domain: {
                      has_mx_or_a_record: true,
                      has_valid_address_syntax: true,
                      is_suspected_disposable_address: false,
                    },
                    local_part: { is_suspected_role_address: false },
                  },
                  email: 'cedric@fogowl.com',
                  host: 'fogowl.com',
                  ip_address: '192.168.1.1',
                  local: 'cedric',
                  score: 0.85021,
                  verdict: 'Valid',
                },
              },
            },
          },
        },
      },
    },
  },
  security: [{ Authorization: [] }],
})

export const getVerifiedSendersRoute = createRoute({
  method: 'get',
  path: '/verified_senders',
  tags: ['Sender Verification'],
  summary: 'Get All Verified Senders',
  description:
    '**This endpoint allows you to retrieve all the Sender Identities associated with an account.**\n\nThis endpoint will return both verified and unverified senders.\n\nYou can limit the number of results returned using the `limit`, `lastSeenID`, and `id` query string parameters.\n\n* `limit` allows you to specify an exact number of Sender Identities to return.\n* `lastSeenID` will return senders with an ID number occuring after the passed in ID. In other words, the `lastSeenID` provides a starting point from which SendGrid will iterate to find Sender Identities associated with your account.\n* `id` will return information about only the Sender Identity passed in the request.',
  operationId: 'GET_verified_senders',
  request: {
    query: z.object({
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'limit', schema: { type: 'number' }, required: false },
        }),
      lastSeenID: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'lastSeenID', schema: { type: 'number' }, required: false },
        }),
      id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'id', schema: { type: 'integer' }, required: false },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({ results: z.array(VerifiedSenderResponseSchemaSchema).exactOptional() })
            .openapi({ required: [] }),
          examples: {
            response: {
              value: {
                results: [
                  {
                    address: '1234 Fake St.',
                    address2: 'PO Box 1234',
                    city: 'San Francisco',
                    country: 'USA',
                    from_email: 'orders@example.com',
                    from_name: 'Example Orders',
                    id: 1234,
                    locked: false,
                    nickname: 'Example Orders',
                    reply_to: 'orders@example.com',
                    reply_to_name: 'Example Orders',
                    state: 'CA',
                    verified: true,
                    zip: '94105',
                  },
                  {
                    address: '1234 Fake St.',
                    address2: 'PO Box 1234',
                    city: 'San Francisco',
                    country: 'USA',
                    from_email: 'support@example.com',
                    from_name: 'Example Support',
                    id: 1235,
                    locked: false,
                    nickname: 'Example Support',
                    reply_to: 'support@example.com',
                    reply_to_name: 'Example Support',
                    state: 'CA',
                    verified: true,
                    zip: '94105',
                  },
                ],
              },
            },
          },
        },
      },
    },
    401: TraitGlobalErrors_401Response,
    403: TraitGlobalErrors_403Response,
    404: TraitGlobalErrors_404Response,
    500: TraitGlobalErrors_500Response,
  },
  security: [{ Authorization: [] }],
})

