export const getWhitelabelIpsRoute = createRoute({
  method: 'get',
  path: '/whitelabel/ips',
  tags: ['Reverse DNS'],
  summary: 'Retrieve all reverse DNS records',
  description:
    '**This endpoint allows you to retrieve all of the Reverse DNS records created by this account.**\n\nYou may include a search key by using the `ip` query string parameter. This enables you to perform a prefix search for a given IP segment (e.g., `?ip="192."`).\n\nUse the `limit` query string parameter to reduce the number of records returned. All records will be returned if you have fewer records than the specified limit.\n\nThe `offset` query string parameter allows you to specify a non-zero index from which records will be returned. For example, if you have ten records, `?offset=5` will return the last five records (at indexes 5 through 9). The list starts at index zero.',
  operationId: 'GET_whitelabel-ips',
  request: {
    query: z.object({
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of results to retrieve.',
            in: 'query',
            name: 'limit',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      offset: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'The point in the list of results to begin retrieving IP addresses from.',
            in: 'query',
            name: 'offset',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      ip: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: "The IP address segment that you'd like to use in a prefix search.",
            in: 'query',
            name: 'ip',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
    headers: z.object({ 'on-behalf-of': TraitOnBehalfOfSubuserOnBehalfOfParamsSchema }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z.array(ReverseDnsSchema),
          examples: {
            response: {
              value: [
                {
                  a_record: {
                    data: '192.168.1.1',
                    host: 'o1.email.example.com',
                    type: 'a',
                    valid: true,
                  },
                  domain: 'example.com',
                  id: 1,
                  ip: '192.168.1.1',
                  legacy: false,
                  rdns: 'o1.email.example.com',
                  subdomain: 'email',
                  users: [
                    { user_id: 7, username: 'john@example.com' },
                    { user_id: 8, username: 'jane@example.com' },
                  ],
                  valid: true,
                },
                {
                  a_record: {
                    data: '192.168.1.2',
                    host: 'o2.email.example.com',
                    type: 'a',
                    valid: true,
                  },
                  domain: 'example.com',
                  id: 2,
                  ip: '192.168.1.2',
                  legacy: false,
                  rdns: 'o2.email.example.com',
                  subdomain: 'email',
                  users: [
                    { user_id: 7, username: 'john@example.com' },
                    { user_id: 9, username: 'jane@example2.com' },
                  ],
                  valid: true,
                },
              ],
            },
          },
        },
      },
    },
  },
  security: [{ Authorization: [] }],
})

