export const getWhitelabelLinksIdRoute = createRoute({
  method: 'get',
  path: '/whitelabel/links/{id}',
  tags: ['Link branding'],
  summary: 'Retrieve a branded link',
  description:
    '**This endpoint allows you to retrieve a specific branded link by providing its ID.**\n\nYou can submit this request as one of your subusers if you include their ID in the `on-behalf-of` header in the request.',
  operationId: 'GET_whitelabel-links-id',
  request: {
    params: z.object({
      id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            description: 'The ID of the branded link you want to retrieve.',
            in: 'path',
            name: 'id',
            required: true,
            schema: { type: 'integer' },
          },
        }),
    }),
    headers: z.object({ 'on-behalf-of': TraitOnBehalfOfSubuserOnBehalfOfParamsSchema }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: LinkBranding_200ResponseSchema,
          examples: {
            response: {
              value: {
                default: false,
                dns: {
                  domain_cname: {
                    data: 'sendgrid.net',
                    host: 'mail.example.com',
                    type: 'cname',
                    valid: true,
                  },
                  owner_cname: {
                    data: 'sendgrid.net',
                    host: '7.example.com',
                    type: 'cname',
                    valid: true,
                  },
                },
                domain: 'example.com',
                id: 1,
                legacy: false,
                subdomain: 'mail',
                user_id: 7,
                username: 'john@example.com',
                valid: true,
              },
            },
          },
        },
      },
    },
  },
  security: [{ Authorization: [] }],
})

