export const postWhitelabelLinksIdValidateRoute = createRoute({
  method: 'post',
  path: '/whitelabel/links/{id}/validate',
  tags: ['Link branding'],
  summary: 'Validate a branded link',
  description:
    '**This endpoint allows you to validate a branded link.**\n\nYou can submit this request as one of your subusers if you include their ID in the `on-behalf-of` header in the request.',
  operationId: 'POST_whitelabel-links-id-validate',
  request: {
    params: z.object({
      id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            description: 'The ID of the branded link that you want to validate.',
            in: 'path',
            name: 'id',
            required: true,
            schema: { type: 'integer' },
          },
        }),
    }),
    headers: z.object({ 'on-behalf-of': TraitOnBehalfOfSubuserOnBehalfOfParamsSchema }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              id: z.int().openapi({ description: 'The ID of the branded link.' }),
              valid: z
                .union([z.literal(true), z.literal(false)])
                .openapi({ description: 'Indicates if the link branding is valid.' }),
              validation_results: z
                .object({
                  domain_cname: z
                    .object({
                      reason: z
                        .string()
                        .nullable()
                        .openapi({
                          description:
                            'Null if the DNS record is valid. If the DNS record is invalid, this will explain why.',
                        }),
                      valid: z
                        .union([z.literal(true), z.literal(false)])
                        .openapi({ description: 'Indicates if this DNS record is valid.' }),
                    })
                    .openapi({
                      description:
                        'The DNS record generated for the sending domain used for this branded link.',
                      required: ['valid', 'reason'],
                    }),
                  owner_cname: z
                    .object({
                      reason: z
                        .string()
                        .nullable()
                        .openapi({
                          description:
                            'Null if valid. If the DNS record is invalid, this will explain why.',
                        }),
                      valid: z
                        .union([z.literal(true), z.literal(false)])
                        .openapi({ description: 'Indicates if the DNS record is valid.' }),
                    })
                    .exactOptional()
                    .openapi({
                      description: 'The DNS record created to verify the branded link.',
                      required: ['valid', 'reason'],
                    }),
                })
                .openapi({
                  description:
                    'The individual validation results for each of the DNS records associated with this branded link.',
                  required: ['domain_cname'],
                }),
            })
            .openapi({ required: ['id', 'valid', 'validation_results'] }),
          examples: {
            response: {
              value: {
                id: 1,
                valid: true,
                validation_results: {
                  domain_cname: {
                    reason: 'Expected CNAME to match "sendgrid.net." but found "example.com.".',
                    valid: false,
                  },
                  owner_cname: { reason: null, valid: true },
                },
              },
            },
          },
        },
      },
    },
    500: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              errors: z
                .array(
                  z
                    .object({
                      message: z
                        .string()
                        .openapi({
                          description: 'The reason why the link whitelabel could not be validated.',
                        }),
                    })
                    .openapi({ required: ['message'] }),
                )
                .openapi({ description: 'The reasons why the validation failed.' }),
            })
            .openapi({ required: ['errors'] }),
          examples: {
            response: { value: { errors: [{ message: 'internal error getting CNAME' }] } },
          },
        },
      },
    },
  },
  security: [{ Authorization: [] }],
})

